package com.qfc.rag;
import com.qfc.auth.*; import com.qfc.common.ApiResponse; import java.util.Map; import javax.servlet.http.HttpServletRequest; import org.springframework.web.bind.annotation.*;
@RestController public class RagController { private final RagService rag; private final CurrentUserResolver users; public RagController(RagService r,CurrentUserResolver u){rag=r;users=u;} @PostMapping("/api/space/projects/{projectId}/knowledge-files/{fileId}") public ApiResponse<Boolean> include(@PathVariable Long projectId,@PathVariable Long fileId,HttpServletRequest req){rag.include(projectId, fileId, users.resolveSite(req));return ApiResponse.success(Boolean.TRUE);} @PostMapping("/api/space/projects/{projectId}/chat") public ApiResponse<Map<String,Object>> chat(@PathVariable Long projectId,@RequestBody Map<String,String> body,HttpServletRequest req){return ApiResponse.success(rag.chat(projectId,body.get("question"),users.resolveSite(req)));} }
